# Run meaningful Swift client contract checks against the actual production types.
# Usage: python3 supabase/tests/family_links/remote_settings_client_test.py
from pathlib import Path
import subprocess, tempfile
root = Path(__file__).resolve().parents[3]
source = (root / 'FamilyTreeV2/FamilyTreeV2/Core/RemoteSettings.swift').read_text()
core = source[source.index('enum ConfigValue:'):source.index('struct RemoteConfigMeta:')]
checks = '\nfunc check(_ condition: Bool, _ title: String) {\n    guard condition else { fatalError(title) }\n    print("PASS: " + title)\n}\nlet cache = RemoteSettingsCache.shared\ncache.replace(["news_max_photos": .number(8), "privacy_url": .string("https://example.org/privacy"), "announce_preset_titles": .array([.string("دعوة")])])\ncheck(RemoteSettings.int("news_max_photos", 5, range: 1...10) == 8, "server photo limit replaces default")\ncache.replace(["news_max_photos": .number(99)])\ncheck(RemoteSettings.int("news_max_photos", 5, range: 1...10) == 5, "out-of-range uses safe default")\ncache.replace(["news_max_photos": .string("7")])\ncheck(RemoteSettings.int("news_max_photos", 5, range: 1...10) == 5, "wrong type cannot change limit")\ncache.replace(["news_max_photos": .number(2.5)])\ncheck(RemoteSettings.int("news_max_photos", 5, range: 1...10) == 5, "fractional limit uses default")\ncache.replace(["site_url": .string("https://example.org"), "sms_otp_template": .string("private scope")])\nlet persisted = UserDefaults.standard.data(forKey: "remote.publicSettings")!\nlet publicValues = try JSONDecoder().decode([String: ConfigValue].self, from: persisted)\ncheck(publicValues["site_url"] != nil && publicValues["sms_otp_template"] == nil, "only public settings persist")\ncache.clearMemberValues()\ncheck(cache.value("sms_otp_template") == nil && cache.value("site_url") != nil, "sign-out clears member settings while preserving public links")\ncache.replace(["notify_news_like_body": .string("{name} test")])\ncheck(RemoteSettings.template("notify_news_like_body", fallback: "fallback", name: "Ali") == "Ali test", "template substitutes the supplied member name")\ncheck(RemoteSettings.text("unknown", "safe") == "safe", "missing key is backwards compatible")\nfor value: ConfigValue in [.bool(true), .number(7), .string("نص"), .array([.string("دعوة")]), .object(["a": .null]), .null] {\n    let data = try JSONEncoder().encode(value)\n    let decoded = try JSONDecoder().decode(ConfigValue.self, from: data)\n    check(decoded == value, "typed JSON round trip")\n}\ncache.replace(["notify_news_like_title": .string("إعجاب جديد")])\ncheck(RemoteSettings.text("notify_news_like_title", "New Like") == "New Like", "default notifications retain existing translations")\ncache.replace(["notify_news_like_title": .string("عنوان جديد")])\ncheck(RemoteSettings.text("notify_news_like_title", "New Like") == "عنوان جديد", "owner text overrides the localized default")\ncache.replace([:])\n'
with tempfile.TemporaryDirectory() as tmp:
    file = Path(tmp) / 'check.swift'
    file.write_text('import Foundation\n' + core + checks)
    subprocess.run(['swift', str(file)], check=True)
